SELECT sum(1) AS sample_count, sum(bs.weight) AS units_count, sum(bs."out.electricity.total.energy_consumption..kwh" * bs.weight) AS "electricity.total.energy_consumption..kwh" FROM comstock_amy2018_r2_2025_md_agg_by_state_and_county_parquet AS bs WHERE bs.applicability = true AND bs.upgrade = 0 AND (bs.bldg_id, bs.county, bs.state) IN ((1, 'G0100010', 'AL'), (1, 'G0100050', 'AL'), (1, 'G0100070', 'AL'), (1, 'G0100090', 'AL'), (1, 'G0100130', 'AL'), (1, 'G0100150', 'AL'), (1, 'G0100170', 'AL'), (1, 'G0100190', 'AL'), (1, 'G0100210', 'AL'), (1, 'G0100250', 'AL'), (1, 'G0100270', 'AL'), (1, 'G0100310', 'AL'), (1, 'G0100330', 'AL'), (1, 'G0100350', 'AL'), (1, 'G0100390', 'AL'), (1, 'G0100410', 'AL'), (1, 'G0100430', 'AL'), (1, 'G0100450', 'AL'), (1, 'G0100470', 'AL'), (1, 'G0100490', 'AL')) AND bs.state = 'CO'